ALTER TABLE properties ADD COLUMN code text,ADD COLUMN floors integer CHECK(floors>0),ADD COLUMN segment text CHECK(segment IN ('Mahasiswi','Karyawati','Mahasiswi & karyawati')),ADD COLUMN address text,ADD COLUMN contact_phone text,ADD COLUMN contact_email text,ADD COLUMN version integer NOT NULL DEFAULT 1 CHECK(version>0),ADD COLUMN archived_at timestamptz;
CREATE UNIQUE INDEX unique_property_code ON properties(organization_id,lower(code)) WHERE code IS NOT NULL;
CREATE TABLE saas_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,label text NOT NULL,kind text NOT NULL CHECK(kind IN ('development','commercial')),room_limit integer NOT NULL CHECK(room_limit>0),property_limit integer NOT NULL CHECK(property_limit>0),staff_limit integer NOT NULL CHECK(staff_limit>0),price_idr bigint CHECK(price_idr>=0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organization_entitlements(organization_id uuid PRIMARY KEY REFERENCES organizations(id),plan_id uuid NOT NULL REFERENCES saas_plans(id),plan_kind text NOT NULL CHECK(plan_kind IN ('development','commercial')),room_limit integer NOT NULL CHECK(room_limit>0),property_limit integer NOT NULL CHECK(property_limit>0),staff_limit integer NOT NULL CHECK(staff_limit>0),state text NOT NULL CHECK(state IN ('trial','active','grace','restricted','cancelled')),valid_until timestamptz,grace_until timestamptz,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),CHECK(plan_kind='development' OR valid_until IS NOT NULL));
CREATE TABLE deployment_plan_defaults(id boolean PRIMARY KEY DEFAULT true CHECK(id),plan_id uuid NOT NULL REFERENCES saas_plans(id),trial_days integer CHECK(trial_days>0));
CREATE TABLE entitlement_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),actor_id uuid REFERENCES users(id),event text NOT NULL,source text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE organization_entitlements ENABLE ROW LEVEL SECURITY;ALTER TABLE organization_entitlements FORCE ROW LEVEL SECURITY;
CREATE POLICY entitlement_read ON organization_entitlements FOR SELECT TO kost_app USING(organization_id=current_org() AND EXISTS(SELECT FROM memberships m WHERE m.organization_id=organization_entitlements.organization_id AND m.user_id=current_actor() AND m.revoked_at IS NULL));
GRANT SELECT ON organization_entitlements,saas_plans TO kost_app;
CREATE FUNCTION provision_organization_entitlement(org uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE p public.saas_plans%ROWTYPE;days integer;BEGIN IF org IS DISTINCT FROM public.current_org() OR NOT public.is_org_owner(org) THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0404';END IF;IF EXISTS(SELECT 1 FROM public.organization_entitlements WHERE organization_id=org) THEN RETURN;END IF;SELECT plan.*,d.trial_days INTO p.id,p.code,p.label,p.kind,p.room_limit,p.property_limit,p.staff_limit,p.price_idr,p.created_at,days FROM public.deployment_plan_defaults d JOIN public.saas_plans plan ON plan.id=d.plan_id WHERE d.id;IF p.id IS NULL THEN RETURN;END IF;IF p.kind='development' AND coalesce(current_setting('app.runtime_environment',true),'') NOT IN ('development','test') THEN RETURN;END IF;IF p.kind='commercial' AND days IS NULL THEN RETURN;END IF;INSERT INTO public.organization_entitlements(organization_id,plan_id,plan_kind,room_limit,property_limit,staff_limit,state,valid_until) VALUES(org,p.id,p.kind,p.room_limit,p.property_limit,p.staff_limit,'trial',CASE WHEN p.kind='commercial' THEN clock_timestamp()+make_interval(days=>days) END) ON CONFLICT DO NOTHING;INSERT INTO public.entitlement_events(organization_id,actor_id,event,source) VALUES(org,public.current_actor(),'initial_trial',CASE WHEN p.kind='development' THEN 'development_fixture' ELSE 'configured_trial' END);END $$;
REVOKE ALL ON FUNCTION provision_organization_entitlement(uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION provision_organization_entitlement(uuid) TO kost_app;
CREATE TABLE room_types(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,property_id uuid NOT NULL,name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 100),default_capacity integer NOT NULL CHECK(default_capacity>0),default_facilities text[] NOT NULL DEFAULT '{}',version integer NOT NULL DEFAULT 1 CHECK(version>0),archived_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,property_id,id),FOREIGN KEY(organization_id,property_id) REFERENCES properties(organization_id,id));
CREATE UNIQUE INDEX room_type_name_unique ON room_types(organization_id,property_id,lower(name));
CREATE TABLE room_type_versions(organization_id uuid NOT NULL,property_id uuid NOT NULL,type_id uuid NOT NULL,version integer NOT NULL,default_capacity integer NOT NULL,default_facilities text[] NOT NULL,name text NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,property_id,type_id,version),FOREIGN KEY(organization_id,property_id,type_id) REFERENCES room_types(organization_id,property_id,id));
CREATE TABLE inventory_batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,property_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),seed_key text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,property_id,id),FOREIGN KEY(organization_id,property_id) REFERENCES properties(organization_id,id));
CREATE UNIQUE INDEX pilot_seed_once ON inventory_batches(organization_id,property_id,seed_key) WHERE seed_key IS NOT NULL;
CREATE TABLE rooms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,property_id uuid NOT NULL,code text NOT NULL CHECK(length(trim(code)) BETWEEN 1 AND 32),floor integer NOT NULL CHECK(floor>0),type_id uuid NOT NULL,type_version integer NOT NULL,capacity integer NOT NULL CHECK(capacity>0),facilities text[] NOT NULL DEFAULT '{}',condition text NOT NULL DEFAULT 'inspection' CHECK(condition IN ('inspection','ready','dirty','maintenance','inactive')),version integer NOT NULL DEFAULT 1 CHECK(version>0),batch_id uuid,archived_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,property_id,id),FOREIGN KEY(organization_id,property_id) REFERENCES properties(organization_id,id),FOREIGN KEY(organization_id,property_id,type_id,type_version) REFERENCES room_type_versions(organization_id,property_id,type_id,version),FOREIGN KEY(organization_id,property_id,batch_id) REFERENCES inventory_batches(organization_id,property_id,id));
CREATE UNIQUE INDEX room_code_unique_all_history ON rooms(organization_id,property_id,lower(code));
CREATE INDEX room_property_page ON rooms(organization_id,property_id,id);
CREATE TABLE room_checklists(organization_id uuid NOT NULL,property_id uuid NOT NULL,room_id uuid NOT NULL,water boolean NOT NULL DEFAULT false,electric boolean NOT NULL DEFAULT false,lock boolean NOT NULL DEFAULT false,furniture boolean NOT NULL DEFAULT false,clean boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,recorded_by uuid REFERENCES users(id),recorded_at timestamptz,PRIMARY KEY(room_id),FOREIGN KEY(organization_id,property_id,room_id) REFERENCES rooms(organization_id,property_id,id));
CREATE TABLE room_checklist_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,property_id uuid NOT NULL,room_id uuid NOT NULL,room_version integer NOT NULL,water boolean NOT NULL,electric boolean NOT NULL,lock boolean NOT NULL,furniture boolean NOT NULL,clean boolean NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,property_id,room_id) REFERENCES rooms(organization_id,property_id,id));
CREATE TABLE room_previews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,property_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),checksum text NOT NULL UNIQUE,payload jsonb NOT NULL,type_version integer NOT NULL,property_version integer NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '15 minutes',consumed_at timestamptz,batch_id uuid,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,property_id) REFERENCES properties(organization_id,id),FOREIGN KEY(organization_id,property_id,batch_id) REFERENCES inventory_batches(organization_id,property_id,id));
CREATE FUNCTION can_manage_inventory(org uuid,location uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$SELECT org=public.current_org() AND EXISTS(SELECT 1 FROM public.memberships m WHERE m.organization_id=org AND m.user_id=public.current_actor() AND m.revoked_at IS NULL AND m.role IN ('Owner','Manager') AND (m.role='Owner' OR EXISTS(SELECT 1 FROM public.location_access a WHERE a.organization_id=org AND a.membership_id=m.id AND a.property_id=location)))$$;
REVOKE ALL ON FUNCTION can_manage_inventory(uuid,uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION can_manage_inventory(uuid,uuid) TO kost_app;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['room_types','room_type_versions','inventory_batches','rooms','room_checklists','room_checklist_events','room_previews'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY inventory_read ON %I FOR SELECT TO kost_app USING(organization_id=current_org() AND can_access_location(organization_id,property_id))',t);END LOOP;END $$;
CREATE POLICY type_insert ON room_types FOR INSERT TO kost_app WITH CHECK(can_manage_inventory(organization_id,property_id));CREATE POLICY type_update ON room_types FOR UPDATE TO kost_app USING(can_manage_inventory(organization_id,property_id)) WITH CHECK(can_manage_inventory(organization_id,property_id));
CREATE POLICY room_insert ON rooms FOR INSERT TO kost_app WITH CHECK(can_manage_inventory(organization_id,property_id));CREATE POLICY room_update ON rooms FOR UPDATE TO kost_app USING(can_manage_inventory(organization_id,property_id)) WITH CHECK(can_manage_inventory(organization_id,property_id));
CREATE POLICY batch_insert ON inventory_batches FOR INSERT TO kost_app WITH CHECK(can_manage_inventory(organization_id,property_id) AND actor_id=current_actor());
CREATE POLICY preview_insert ON room_previews FOR INSERT TO kost_app WITH CHECK(can_manage_inventory(organization_id,property_id) AND actor_id=current_actor());CREATE POLICY preview_update ON room_previews FOR UPDATE TO kost_app USING(can_manage_inventory(organization_id,property_id) AND actor_id=current_actor()) WITH CHECK(can_manage_inventory(organization_id,property_id) AND actor_id=current_actor());
CREATE POLICY checklist_insert ON room_checklists FOR INSERT TO kost_app WITH CHECK(can_manage_inventory(organization_id,property_id));
CREATE POLICY checklist_update ON room_checklists FOR UPDATE TO kost_app USING(organization_id=current_org() AND can_access_location(organization_id,property_id) AND EXISTS(SELECT 1 FROM memberships m WHERE m.organization_id=room_checklists.organization_id AND m.user_id=current_actor() AND m.revoked_at IS NULL AND m.role IN ('Owner','Manager','Operations'))) WITH CHECK(organization_id=current_org() AND can_access_location(organization_id,property_id));
CREATE POLICY checklist_event_insert ON room_checklist_events FOR INSERT TO kost_app WITH CHECK(organization_id=current_org() AND actor_id=current_actor() AND can_access_location(organization_id,property_id) AND EXISTS(SELECT 1 FROM memberships m WHERE m.organization_id=room_checklist_events.organization_id AND m.user_id=current_actor() AND m.revoked_at IS NULL AND m.role IN ('Owner','Manager','Operations')));
CREATE POLICY property_update ON properties FOR UPDATE TO kost_app USING(organization_id=current_org() AND is_org_owner(organization_id)) WITH CHECK(organization_id=current_org() AND is_org_owner(organization_id));
GRANT SELECT ON room_types,room_type_versions,inventory_batches,rooms,room_checklists,room_checklist_events,room_previews TO kost_app;
GRANT INSERT,UPDATE ON room_types,rooms,room_checklists,room_previews TO kost_app;GRANT INSERT ON room_checklist_events,inventory_batches TO kost_app;
GRANT UPDATE(code,floors,segment,address,contact_phone,contact_email,version) ON properties TO kost_app;
